    const blob2 = getAssetAsBlob('utf8_test_text.txt');

    const text = await blob2.text();

    assert.strictEqual(text, textAssetOnDisk);

  }

  test().then(() => {

    called = true;

  });

  process.on('exit', () => {

    assert(called);

